mapper.select:
SELECT MAX(unit_code) 
FROM smd_learning_unit 
WHERE course_id = #{courseId} 
  AND parent_id = #{parentId}
  AND status = '1'

mapper.delete:
DELETE FROM smd_learning_unit 
WHERE course_id = #{courseId} 
  AND unit_code LIKE #{unitCodePattern}

